package main

import (
	"bufio"
	"fmt"
	"go/scanner"
	"go/token"
	"os"
)

func main() {
	for _, name := range os.Args[1:] {
		file, err := os.Open(name)
		if err != nil {
			panic(err)
		}
		physical := 0
		lineScanner := bufio.NewScanner(file)
		for lineScanner.Scan() {
			physical++
		}
		if err := lineScanner.Err(); err != nil {
			panic(err)
		}
		file.Close()

		source, err := os.ReadFile(name)
		if err != nil {
			panic(err)
		}
		fset := token.NewFileSet()
		fileSet := fset.AddFile(name, -1, len(source))
		var sourceScanner scanner.Scanner
		sourceScanner.Init(fileSet, source, nil, scanner.ScanComments)
		tokens := map[int]bool{}
		for {
			position, kind, _ := sourceScanner.Scan()
			if kind == token.EOF {
				break
			}
			if kind != token.COMMENT {
				tokens[fileSet.Position(position).Line] = true
			}
		}
		fmt.Printf("%s physical=%d code=%d\n", name, physical, len(tokens))
	}
}
